import React from 'react';

function Sidebar({ currentView, onViewChange, onLogout, isOpen, onToggle }) {
  const user = JSON.parse(localStorage.getItem('user') || '{}');
  const isAdmin = user.role === 'admin';

  return (
    <>
      {/* Hamburger Menu */}
      <div 
        className="hamburger-menu" 
        onClick={onToggle}
        style={{
          position: 'fixed',
          top: '20px',
          left: isOpen ? '270px' : '20px',
          zIndex: 1001,
          cursor: 'pointer',
          padding: '10px',
          backgroundColor: isOpen ? 'white' : 'transparent',
          borderRadius: '4px',
          transition: 'left 0.3s ease, background-color 0.3s ease'
        }}
      >
        <div style={{ width: '25px', height: '3px', backgroundColor: isOpen ? '#2c3e50' : 'white', margin: '5px 0', transition: 'all 0.3s' }}></div>
        <div style={{ width: '25px', height: '3px', backgroundColor: isOpen ? '#2c3e50' : 'white', margin: '5px 0', transition: 'all 0.3s' }}></div>
        <div style={{ width: '25px', height: '3px', backgroundColor: isOpen ? '#2c3e50' : 'white', margin: '5px 0', transition: 'all 0.3s' }}></div>
      </div>

      {/* Overlay */}
      {isOpen && (
        <div 
          className="sidebar-overlay"
          onClick={onToggle}
          style={{
            position: 'fixed',
            top: 0,
            left: 0,
            right: 0,
            bottom: 0,
            backgroundColor: 'rgba(0, 0, 0, 0.5)',
            zIndex: 999
          }}
        />
      )}

      {/* Sidebar */}
      <div className={`sidebar ${isOpen ? 'open' : ''}`}>
        <div className="sidebar-header">
          <h2>Task Manager</h2>
          <div className="user-info">
            <div className="user-name">{user.name}</div>
            <div className="user-role">{user.role}</div>
          </div>
        </div>

        <nav className="sidebar-nav">
          <button
            className={`nav-item ${currentView === 'tasks' ? 'active' : ''}`}
            onClick={() => onViewChange('tasks')}
          >
            📋 My Tasks
          </button>
          <button
            className={`nav-item ${currentView === 'calendar' ? 'active' : ''}`}
            onClick={() => onViewChange('calendar')}
          >
            📅 Calendar
          </button>
          {isAdmin && (
            <button
              className={`nav-item ${currentView === 'templates' ? 'active' : ''}`}
              onClick={() => onViewChange('templates')}
            >
              ⚙️ Manage Templates
            </button>
          )}
        </nav>

        <div className="sidebar-footer">
          <button className="btn btn-secondary btn-block" onClick={onLogout}>
            Logout
          </button>
        </div>
      </div>
    </>
  );
}

export default Sidebar;
